package com.personal.assistant.module.reminder.controller;import com.personal.assistant.common.response.ApiResponse;import com.personal.assistant.common.security.SecurityContextHelper;import com.personal.assistant.module.reminder.dto.*;import com.personal.assistant.module.reminder.entity.*;import com.personal.assistant.module.reminder.service.ReminderService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/reminders") public class ReminderController {private final ReminderService service;public ReminderController(ReminderService s){service=s;}private Long uid(){return SecurityContextHelper.currentUserId();}@GetMapping public ApiResponse<List<Reminder>> list(@RequestParam(required=false)String status){return ApiResponse.success(service.list(uid(),status));}@PostMapping public ApiResponse<Long> create(@Valid @RequestBody ReminderRequest r){return ApiResponse.success(service.create(uid(),r));}@PutMapping("/{id}")public ApiResponse<Void> update(@PathVariable Long id,@Valid @RequestBody ReminderRequest r){service.update(uid(),id,r);return ApiResponse.success();}@PatchMapping("/{id}/status")public ApiResponse<Void> status(@PathVariable Long id,@RequestParam String status){service.status(uid(),id,status);return ApiResponse.success();}@GetMapping("/channels")public ApiResponse<List<ChannelResponse>> channels(){return ApiResponse.success(service.listChannels(uid()));}@PostMapping("/channels")public ApiResponse<Long> channel(@Valid @RequestBody ChannelRequest r){return ApiResponse.success(service.saveChannel(uid(),null,r));}@PutMapping("/channels/{id}")public ApiResponse<Long> channel(@PathVariable Long id,@Valid @RequestBody ChannelRequest r){return ApiResponse.success(service.saveChannel(uid(),id,r));}@PostMapping("/channels/{id}/test")public ApiResponse<Void> test(@PathVariable Long id){service.testChannel(uid(),id);return ApiResponse.success();}@DeleteMapping("/channels/{id}")public ApiResponse<Void> deleteChannel(@PathVariable Long id){service.deleteChannel(uid(),id);return ApiResponse.success();}@GetMapping("/logs")public ApiResponse<List<NotificationLog>> logs(){return ApiResponse.success(service.listLogs(uid()));}}